// Kronos Bot — cierre TP/SL (puente MT4): parsea cada archivo leído de
// mt4-bridge/orders/closed/{ticket}.json (formato en
// mt4-bridge/FORMATO_ARCHIVOS.md sección 5.1).
// Mismo patrón que 'Parsear resultado (MT4)': binario en modo
// filesystem-v2, se lee con this.helpers.getBinaryDataBuffer.
const results = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaryMeta = item.binary.data;
  const fullPath = `${binaryMeta.directory}/${binaryMeta.fileName}`;
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const parsed = JSON.parse(buffer.toString('utf-8'));

  results.push({
    json: {
      ticket: parsed.ticket,
      signal_uid: parsed.signal_uid,
      symbol: parsed.symbol,
      reason: parsed.reason,
      close_price: parsed.close_price,
      profit: parsed.profit,
      close_time: parsed.close_time,
      fileName: fullPath,
    },
  });
}

return results;

// Kronos Bot — cierre TP/SL: borra el archivo de
// mt4-bridge/orders/closed/{ticket}.json ya procesado.
// Se ejecuta siempre (haya notificado o no) — mismo criterio que
// 'Borrar archivo de resultado'. fileName se recupera del nodo
// 'Parsear cierre (MT4)' porque el nodo Postgres intermedio reemplaza
// item.json por las columnas devueltas por la query.
const fs = require('fs');

const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const paired = items[i].pairedItem;
  const idx = Array.isArray(paired) ? paired[0].item : paired.item;
  const fileName = $('Parsear cierre (MT4)').all()[idx].json.fileName;
  await fs.promises.unlink(fileName);
}

return items;
